<div class="auth-wrap"><form class="auth-card stack" method="post" action="<?= e(url('/login')) ?>"><?= csrf_field() ?><img class="brand-mini" src="<?= e(asset('brand/logo-mark.png')) ?>" alt="<?= e(setting('company_name', 'AtteCert')) ?>"><h1><?= e(__('auth.login')) ?></h1><?php if (error('email')): ?><p class="form-error"><?= e(error('email')) ?></p><?php endif; ?><label><?= e(__('fields.email')) ?><input type="email" name="email" value="<?= e((string) old('email')) ?>" required autocomplete="username"></label><label><?= e(__('fields.password')) ?><input type="password" name="password" required autocomplete="current-password"></label><button class="btn btn-primary" type="submit"><?= e(__('auth.login')) ?></button><a href="<?= e(url('/forgot-password')) ?>"><?= e(__('auth.forgot')) ?></a><a href="<?= e(url('/register')) ?>"><?= e(__('auth.need_account')) ?></a></form></div>
